opaqueStyles.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-primary: #0c0b0a;
  --bg-secondary: #141311;
  --bg-card: #1a1917;
  --bg-surface: #232220;
  --accent: #ff3600;
  --accent-hover: #e62f00;
  --accent-light: rgba(255, 54, 0, 0.12);
  --text-primary: #ffffff;
  --text-secondary: rgba(255, 255, 255, 0.72);
  --text-muted: rgba(255, 255, 255, 0.48);
  --border: rgba(255, 255, 255, 0.08);
  --border-accent: rgba(255, 54, 0, 0.35);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.6);
  --radius: 20px;
  --radius-sm: 12px;
}

html {
  font-family:
    "Golos Text",
    system-ui,
    -apple-system,
    sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  min-height: 100vh;
}

/* === HEADER === */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(12, 11, 10, 0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
}

.header__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--text-primary);
}

.logo__icon {
  width: 44px;
  height: 44px;
  background: var(--accent);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 18px;
  letter-spacing: -0.03em;
}

.logo__text {
  font-weight: 700;
  font-size: 20px;
  letter-spacing: -0.02em;
}

.logo__text span {
  color: var(--accent);
}

.nav {
  display: flex;
  align-items: center;
  gap: 6px;
}

.nav__link {
  padding: 10px 16px;
  font-weight: 500;
  font-size: 15px;
  color: var(--text-secondary);
  text-decoration: none;
  border-radius: 8px;
  transition:
    color 0.2s,
    background 0.2s;
}

.nav__link:hover {
  color: var(--text-primary);
  background: var(--bg-surface);
}

.nav__link--accent {
  background: var(--accent);
  color: var(--text-primary);
}

.nav__link--accent:hover {
  background: var(--accent-hover);
}

.header__cta {
  display: flex;
  align-items: center;
  gap: 16px;
}

.header__phone {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-primary);
  text-decoration: none;
  font-weight: 600;
  font-size: 16px;
  letter-spacing: -0.01em;
}

/* === HERO === */
.hero {
  padding: 180px 32px 120px;
  background: linear-gradient(
    160deg,
    var(--bg-primary) 0%,
    var(--bg-secondary) 100%
  );
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: "";
  position: absolute;
  top: -200px;
  right: -200px;
  width: 900px;
  height: 900px;
  background: radial-gradient(
    circle,
    rgba(255, 54, 0, 0.1) 0%,
    transparent 65%
  );
  pointer-events: none;
}

.hero__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 64px;
  align-items: center;
}

.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: var(--accent-light);
  border: 1px solid var(--border-accent);
  border-radius: 500px;
  font-weight: 600;
  font-size: 13px;
  color: var(--accent);
  margin-bottom: 24px;
}

.hero__badge::before {
  content: "";
  width: 8px;
  height: 8px;
  background: var(--accent);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.hero__title {
  font-weight: 700;
  font-size: clamp(36px, 5vw, 56px);
  line-height: 1.08;
  letter-spacing: -0.03em;
  margin-bottom: 24px;
}

.hero__title span {
  color: var(--accent);
}

.hero__subtitle {
  font-size: 18px;
  line-height: 1.65;
  color: var(--text-secondary);
  max-width: 540px;
  margin-bottom: 40px;
}

.hero__actions {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 16px 32px;
  font-family: inherit;
  font-weight: 600;
  font-size: 16px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  cursor: pointer;
  border: none;
}

.btn--primary {
  background: var(--accent);
  color: var(--text-primary);
  transition:
    background 0.2s,
    transform 0.2s;
}

.btn--primary:hover {
  background: var(--accent-hover);
  transform: translateY(-2px);
}

.btn--secondary {
  background: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--border);
  transition:
    background 0.2s,
    border-color 0.2s;
}

.btn--secondary:hover {
  background: var(--bg-card);
  border-color: rgba(255, 255, 255, 0.15);
}

.hero__trust {
  display: flex;
  gap: 32px;
  margin-top: 48px;
  padding-top: 40px;
  border-top: 1px solid var(--border);
}

.trust-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.trust-item__value {
  font-weight: 700;
  font-size: 28px;
  letter-spacing: -0.03em;
  color: var(--accent);
}

.trust-item__label {
  font-size: 13px;
  color: var(--text-muted);
}

/* Hero Visual */
.hero__visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__image-frame {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(
    135deg,
    var(--bg-card) 0%,
    var(--bg-surface) 100%
  );
  border-radius: var(--radius);
  border: 1px solid var(--border);
  overflow: hidden;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__image-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      circle at 30% 40%,
      rgba(255, 54, 0, 0.2) 0%,
      transparent 50%
    ),
    radial-gradient(
      circle at 70% 60%,
      rgba(255, 54, 0, 0.1) 0%,
      transparent 40%
    );
}

.hero__checklist {
  position: absolute;
  bottom: -20px;
  left: -30px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 20px 24px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
  animation: float 6s ease-in-out infinite;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

.check-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
}

.check-item::before {
  content: "✓";
  width: 22px;
  height: 22px;
  background: var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  flex-shrink: 0;
}

/* === SECTION === */
.section {
  padding: 100px 32px;
}

.section--alt {
  background: var(--bg-secondary);
}

.section__header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 64px;
}

.section__eyebrow {
  display: inline-block;
  font-weight: 600;
  font-size: 13px;
  color: var(--accent);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.section__title {
  font-weight: 700;
  font-size: clamp(28px, 4vw, 44px);
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.section__desc {
  font-size: 17px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* === PROBLEMS === */
.problems-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.problem-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  display: flex;
  gap: 20px;
  transition:
    border-color 0.3s,
    background 0.3s;
}

.problem-card:hover {
  border-color: var(--border-accent);
  background: var(--accent-light);
}

.problem-card__icon {
  width: 56px;
  height: 56px;
  background: var(--accent-light);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.problem-card__content {
  flex: 1;
}

.problem-card__title {
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.problem-card__desc {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* === HOW IT WORKS === */
.steps {
  max-width: 1100px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  position: relative;
}

.steps::before {
  content: "";
  position: absolute;
  top: 40px;
  left: 15%;
  right: 15%;
  height: 2px;
  background: var(--accent);
  opacity: 0.25;
}

.step {
  text-align: center;
  position: relative;
}

.step__number {
  width: 80px;
  height: 80px;
  background: var(--bg-card);
  border: 2px solid var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 28px;
  color: var(--accent);
  margin: 0 auto 20px;
  position: relative;
  z-index: 1;
}

.step__title {
  font-weight: 700;
  font-size: 17px;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.step__desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* === DIAGNOSTICS TYPES === */
.diagnostics-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.diagnostic-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  transition:
    border-color 0.3s,
    transform 0.3s;
}

.diagnostic-card:hover {
  border-color: var(--border-accent);
  transform: translateY(-4px);
}

.diagnostic-card__icon {
  width: 64px;
  height: 64px;
  background: var(--accent-light);
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

.diagnostic-card__title {
  font-weight: 700;
  font-size: 20px;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.diagnostic-card__desc {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 20px;
}

.diagnostic-card__list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.diagnostic-card__item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: var(--text-secondary);
}

.diagnostic-card__item::before {
  content: "";
  width: 6px;
  height: 6px;
  background: var(--accent);
  border-radius: 50%;
  flex-shrink: 0;
}

/* === PRICING === */
.pricing-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 40px;
  position: relative;
  transition:
    border-color 0.3s,
    background 0.3s;
}

.pricing-card--featured {
  border-color: var(--accent);
  background: linear-gradient(
    180deg,
    var(--accent-light) 0%,
    var(--bg-card) 40%
  );
}

.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--text-primary);
  font-weight: 700;
  font-size: 12px;
  padding: 6px 20px;
  border-radius: 500px;
  letter-spacing: 0.02em;
}

.pricing-card__name {
  font-weight: 700;
  font-size: 24px;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.pricing-card__desc {
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 32px;
}

.pricing-card__price {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 32px;
}

.pricing-card__price-value {
  font-weight: 800;
  font-size: 48px;
  letter-spacing: -0.03em;
}

.pricing-card__price-suffix {
  font-weight: 600;
  font-size: 20px;
  color: var(--text-muted);
}

.pricing-card__features {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-bottom: 32px;
}

.pricing-card__feature {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 15px;
  color: var(--text-secondary);
}

.pricing-card__feature::before {
  content: "✓";
  width: 22px;
  height: 22px;
  background: var(--accent-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: var(--accent);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

/* === ADVANTAGES === */
.advantages-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.advantage-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  text-align: center;
}

.advantage-card__icon {
  width: 64px;
  height: 64px;
  background: var(--accent-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

.advantage-card__title {
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
}

.advantage-card__desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* === TESTIMONIALS === */
.testimonials-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
}

.testimonial-card__stars {
  display: flex;
  gap: 4px;
  margin-bottom: 20px;
}

.testimonial-card__star {
  width: 18px;
  height: 18px;
  background: var(--accent);
  clip-path: polygon(
    50% 0%,
    61% 35%,
    98% 35%,
    68% 57%,
    79% 91%,
    50% 70%,
    21% 91%,
    32% 57%,
    2% 35%,
    39% 35%
  );
}

.testimonial-card__text {
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

.testimonial-card__author {
  display: flex;
  align-items: center;
  gap: 14px;
}

.testimonial-card__avatar {
  width: 48px;
  height: 48px;
  background: var(--bg-surface);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 16px;
  color: var(--accent);
}

.testimonial-card__name {
  font-weight: 600;
  font-size: 15px;
}

.testimonial-card__role {
  font-size: 13px;
  color: var(--text-muted);
}

/* === FAQ === */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.faq-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 24px;
}

.faq-item__question {
  font-weight: 600;
  font-size: 17px;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.faq-item__question::before {
  content: "?";
  width: 28px;
  height: 28px;
  background: var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  flex-shrink: 0;
}

.faq-item__answer {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
  padding-left: 40px;
}

/* === CTA === */
.cta {
  background: linear-gradient(
    135deg,
    var(--bg-card) 0%,
    var(--bg-surface) 100%
  );
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.cta__inner {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
  padding: 100px 32px;
}

.cta__title {
  font-weight: 700;
  font-size: clamp(28px, 4vw, 44px);
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.cta__desc {
  font-size: 18px;
  color: var(--text-secondary);
  margin-bottom: 40px;
}

.cta__form {
  display: flex;
  gap: 16px;
  max-width: 540px;
  margin: 0 auto;
}

.cta__input {
  flex: 1;
  padding: 16px 20px;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 16px;
  outline: none;
  transition: border-color 0.2s;
}

.cta__input::placeholder {
  color: var(--text-muted);
}

.cta__input:focus {
  border-color: var(--accent);
}

.cta__note {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 16px;
}

.cta__phone {
  font-size: 48px;
  font-weight: 700;
  color: var(--text-primary);
  text-decoration: none;
  letter-spacing: -0.02em;
  transition: color 0.2s;
}

.cta__phone:hover {
  color: var(--accent);
}

/* === FOOTER === */
.footer {
  background: var(--bg-primary);
  padding: 64px 32px 32px;
}

.footer__inner {
  max-width: 1280px;
  margin: 0 auto;
}

.footer__top {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--border);
}

.footer__brand-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-top: 16px;
  max-width: 320px;
}

.footer__col-title {
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  margin-bottom: 20px;
  color: var(--text-primary);
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer__link {
  font-size: 14px;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color 0.2s;
}

.footer__link:hover {
  color: var(--text-primary);
}

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
}

.footer__copyright {
  font-size: 14px;
  color: var(--text-muted);
}

.footer__contacts {
  display: flex;
  gap: 24px;
}

.footer__contact {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: var(--text-secondary);
  text-decoration: none;
}

.footer__contact:hover {
  color: var(--text-primary);
}

/* === RESPONSIVE === */
@media (max-width: 1024px) {
  .hero__inner {
    grid-template-columns: 1fr;
    gap: 48px;
  }

  .problems-grid,
  .diagnostics-grid,
  .testimonials-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .steps {
    grid-template-columns: repeat(2, 1fr);
  }

  .steps::before {
    display: none;
  }

  .advantages-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer__top {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .header__inner {
    padding: 0 20px;
  }

  .nav {
    display: none;
  }

  .hero {
    padding: 140px 20px 80px;
  }

  .section {
    padding: 64px 20px;
  }

  .hero__trust {
    gap: 24px;
    flex-wrap: wrap;
  }

  .problems-grid,
  .diagnostics-grid,
  .testimonials-grid,
  .advantages-grid {
    grid-template-columns: 1fr;
  }

  .steps {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .cta__form {
    flex-direction: column;
  }

  .footer__top {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer__bottom {
    flex-direction: column;
    gap: 24px;
    text-align: center;
  }

  .hero__checklist {
    display: none;
  }
}
